import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n0 = int(next(iterator))
        n1 = int(next(iterator))
        n2 = int(next(iterator))

        res = []

        if n0 > 0:
            res.append('0')
            for _ in range(n0):
                res.append('0')

        if n1 > 0:
            if len(res) == 0:
                res.append('0')
                res.append('1')
                n1 -= 1
            elif res[-1] == '0':
                res.append('1')
                n1 -= 1
                while n1 > 0:
                    res.append('0')
                    res.append('1')
                    n1 -= 2
                if n1 == 1:
                    res.append('1')
            else:
                res.append('0')
                res.append('1') if n1 > 0 else None
                n1 -= 1
                while n1 > 0 and n1 % 2 == 0:
                    res.append('0')
                    res.append('0')
                    n1 -= 2
                if n1 == 0:
                    pass
                else:
                    res.append('1')
                    n1 -= 1

        if n2 > 0:
            if len(res) == 0:
                 for _ in range(n2 + 1):
                     res.append('1')
            elif res[-1] == '1':
                for _ in range(n2):
                    res.append('1')
            else:
                res.append(res[-1])
                for _ in range(n2):
                    res.append('1' if res[-1] == '0' else '1')
                if res[-1] != '1':
                    res[-1] = '1'

        if n1 > 0 and len(res) > 0 and res[-1] == '1':
             if n1 % 2 == 0:
                 for _ in range(n1 // 2):
                     res.append('0')
                     res.append('1')
             else:
                 res.append('0')
                 for _ in range((n1 - 1) // 2):
                     res.append('1')
                     res.append('0')
                 res.append('1')

        if n2 > 0 and len(res) > 0 and res[-1] != '1':
             res.append('1')
             for _ in range(n2):
                 res.append('1')

        if n1 > 0 and len(res) > 1 and res[-1] == '0' and res[-2] == '0':
             res.append('1')
             n1 -= 1
             while n1 > 0:
                 res.append('0')
                 res.append('1')
                 n1 -= 2
             if n1 == 1:
                 res.append('1')

        if n1 > 1 and len(res) > 0 and res[-1] == '0':
            res.append('1')
            n1 -= 1
            while n1 > 0:
                res.append('0')
                res.append('0')
                n1 -= 2
            if n1 == 1:
                res.append('1')

        if n2 > 0 and not res:
            res = ['1'] * (n2 + 1)
        elif n2 > 0 and res[-1] != '1':
            res.append('1')
            res.extend(['1'] * n2)

        if n1 > 0:
            if not res:
                res = ['0', '1']
                n1 -= 1
                while n1 > 0 or (n1 == 0 and len(res) < 2):
                    if n1 > 0:
                        res.append('0')
                        res.append('1')
                        n1 -= 2
                    if n1 == 1:
                        res.append('1')
                        n1 -= 1
            elif res[-1] == '0' and n1 > 0:
                res.append('1')
                n1 -= 1
        if n1 > 0 and res[-1] == '1':
            res.append('0')
            n1 -= 1
            while n1 > 1:
                res.append('1')
                res.append('0')
                n1 -= 2

        final_res = "".join(res)
        results.append(final_res)

    print("\n".join(results))
